   FCONTENT     TEXT NOT NULL DEFAULT ''  ,    -- 公告内容
   FISOUTALL     BIT NOT NULL DEFAULT  0 ,    -- 是否外部公开
   FISINALL     BIT NOT NULL DEFAULT  0 ,    -- 是否内部公开
   FNOTE     NVARCHAR(255) NOT NULL DEFAULT '' ,    -- 备注
   FIMAGE     IMAGE NULL  ,    -- 新闻公告图片
