   M_USER				VARCHAR(20)		NOT NULL DEFAULT '',	-- 最后异动帐号
   UID VARCHAR(50) NOT NULL CONSTRAINT [PK_SYS_ENANNOU] PRIMARY KEY NONCLUSTERED
 ) 
END
