   FDATE     DATE NULL  ,    -- 流转卡日期
   FPRODUCTID     VARCHAR(50) NOT NULL DEFAULT '' ,    -- 产品内码
   FUNITID     VARCHAR(50) NOT NULL DEFAULT '' ,    -- 单位内码
   FBATCHNO     VARCHAR(50) NOT NULL DEFAULT '' ,    -- 批次
