IF  NOT EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'T_SFC_PROCESS') AND type in (N'U'))
BEGIN
CREATE TABLE T_SFC_PROCESS(
   FERPCODE     VARCHAR(50) NOT NULL DEFAULT '' ,    -- ERP工序编码
   FK3CODE     VARCHAR(50) NOT NULL DEFAULT '' ,    -- K3工序代码
   FDESCRIPTION     VARCHAR(200) NOT NULL DEFAULT '' ,    -- 备注
   FRETIME     DECIMAL(24,6) NOT NULL DEFAULT 0 ,    -- 标准换型时间(分)
   FPRODUCTID     VARCHAR(50) NOT NULL DEFAULT '' ,    -- 产品代码
   FOVERRATIO     DECIMAL(24,6) NOT NULL DEFAULT 0 ,    -- 超产比例
   FCOSTCENTERID     VARCHAR(50) NOT NULL DEFAULT '' ,    -- 成本中心内码
   FSTADTIME     DECIMAL(24,6) NOT NULL DEFAULT 0 ,    -- 单位标准工时(分)
   FSTADPCOST     DECIMAL(24,6) NOT NULL DEFAULT 0 ,    -- 单位计件工资
   FSTADTCOST     DECIMAL(24,6) NOT NULL DEFAULT 0 ,    -- 单位计时工资
   FWAITTIME     DECIMAL(24,6) NOT NULL DEFAULT 0 ,    -- 等待时间(分)
   FNUMBER     VARCHAR(20) NOT NULL DEFAULT '' ,    -- 工序代码
   FISCLOSESTATUS     INT NOT NULL DEFAULT 0 ,    -- 工序关闭条件
   FCOEFFICIENT     DECIMAL(24,6) NOT NULL DEFAULT 0 ,    -- 工序汇报系数(汇报配比)
   FNAME     NVARCHAR(50) NOT NULL DEFAULT '' ,    -- 工序名称
   FSKILLID     VARCHAR(50) NOT NULL DEFAULT '' ,    -- 工艺技能
   FRPTCTRLPARA     VARCHAR(50) NOT NULL DEFAULT '' ,    -- 汇报控制参数
   FREPORTMODE     INT NOT NULL DEFAULT 0 ,    -- 汇报模式
   FISALLOWFUTURETIME     INT NOT NULL DEFAULT 1 ,    -- 汇报日期是否允许在将来
   FISCONTROLTIME     INT NOT NULL DEFAULT 0 ,    -- 汇报时间
