   M_USER				VARCHAR(20)		NOT NULL DEFAULT '',	-- 最后异动帐号
   UID VARCHAR(50) NOT NULL CONSTRAINT [PK_T_SAL_ORDER] PRIMARY KEY NONCLUSTERED
 ) 
