/* 脚本    说明:T_PUR_MRAPPENTRY 退料通知单明细*/ 
 -- DROP TABLE T_PUR_MRAPPENTRY
IF  NOT EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'T_PUR_MRAPPENTRY') AND type in (N'U'))
BEGIN
CREATE TABLE T_PUR_MRAPPENTRY(
   FROWTYPE     VARCHAR(50) NOT NULL DEFAULT '' ,    -- 产品类型
   FMTONO     VARCHAR(50) NOT NULL DEFAULT '' ,    -- 计划跟踪号
   FMATERIALID     VARCHAR(50) NOT NULL DEFAULT '' ,    -- 物料
   FAUXPROPID     VARCHAR(50) NOT NULL DEFAULT '' ,    -- 辅助属性
   FBASEUNITID     VARCHAR(50) NOT NULL DEFAULT '' ,    -- 基本单位
   FUNITID     VARCHAR(50) NOT NULL DEFAULT '' ,    -- 常用单位
   FMRAPPQTY     DECIMAL(24,6) NOT NULL DEFAULT 0 ,    -- 申请退料数量
   FREPLENISHQTY     DECIMAL(24,6) NOT NULL DEFAULT 0 ,    -- 补料数量
   FKEAPAMTQTY     DECIMAL(24,6) NOT NULL DEFAULT 0 ,    -- 扣款数量
   FRMREASON     VARCHAR(150) NOT NULL DEFAULT '' ,    -- 退料原因
   FSRCID     VARCHAR(50) NOT NULL DEFAULT '' ,    -- 源单内码
   FSRCFORMID     VARCHAR(50) NOT NULL DEFAULT '' ,    -- 源单类型
   FSRCBILLNO     VARCHAR(50) NOT NULL DEFAULT '' ,    -- 源单单据编号
   FSRCDETAILID     VARCHAR(50) NOT NULL DEFAULT '' ,    -- 源单表体内码
   FSRCENTRYID     INT NOT NULL DEFAULT 0 ,    -- 源单行号
   FNOTE     VARCHAR(250) NOT NULL DEFAULT '' ,    -- 备注
   FLOT     VARCHAR(50) NOT NULL DEFAULT '' ,    -- 批次
   FSTOCKID     VARCHAR(50) NOT NULL DEFAULT '' ,    -- 仓库
   FSTOCKLOCID     VARCHAR(50) NOT NULL DEFAULT '' ,    -- 仓位
   FPRICE     DECIMAL(24,6) NOT NULL DEFAULT 0 ,    -- 单价
   FTAXRATE     DECIMAL(24,6) NOT NULL DEFAULT 0 ,    -- 税率%
   FTAXPRICE     DECIMAL(24,6) NOT NULL DEFAULT 0 ,    -- 含税单价
   FMRQTY     DECIMAL(24,6) NOT NULL DEFAULT 0 ,    -- 退料数量
   FDISCOUNTRATE     DECIMAL(24,6) NOT NULL DEFAULT 0 ,    -- 折扣率%
   FDISCOUNT     DECIMAL(24,6) NOT NULL DEFAULT 0 ,    -- 折扣额
   FAMOUNT     DECIMAL(24,6) NOT NULL DEFAULT 0 ,    -- 退料金额
   FAMOUNT_LC     DECIMAL(24,6) NOT NULL DEFAULT 0 ,    -- 金额(本位币)
   FTAXAMOUNT     DECIMAL(24,6) NOT NULL DEFAULT 0 ,    -- 税额
   FTAXAMOUNT_LC     DECIMAL(24,6) NOT NULL DEFAULT 0 ,    -- 税额(本位币)
   FALLAMOUNT     DECIMAL(24,6) NOT NULL DEFAULT 0 ,    -- 价税合计
   FALLAMOUNT_LC     DECIMAL(24,6) NOT NULL DEFAULT 0 ,    -- 价税合计(本位币)
   FGIVEAWAY     BIT NOT NULL DEFAULT  0 ,    -- 是否赠品
   FSTOCKSTATUSID     VARCHAR(50) NOT NULL DEFAULT '' ,    -- 库存状态
   FBASEUNITQTY     DECIMAL(24,6) NOT NULL DEFAULT 0 ,    -- 基本单位数量
