 -- DROP TABLE ODK_SRM_Improve
IF  NOT EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'ODK_SRM_Improve') AND type in (N'U'))
BEGIN
CREATE TABLE ODK_SRM_Improve(
   FDATE     DATE NULL  ,    -- 单据日期
   FEMPID     VARCHAR(50) NOT NULL DEFAULT '' ,    -- 计划员
   FSUPPLYID     VARCHAR(50) NOT NULL DEFAULT '' ,    -- 供应商
   FBILLSTATUS     INT NOT NULL DEFAULT 0 ,    -- 单据状态
   FSOURCETYPE     VARCHAR(50) NOT NULL DEFAULT '' ,    -- 改善类型
   FSUNREPLYDATE     DATE NULL  ,    -- 供应商需回复日期
   FSUREPLYDATE     DATE NULL  ,    -- 供应商回复日期
   FRESULT     VARCHAR(max) NOT NULL DEFAULT '' ,    -- 处理结果
   FFINISHDATE     DATE NULL  ,    -- 改善确认日期
   FREPEATPROBLEM     BIT NOT NULL DEFAULT  0 ,    -- 是否重复问题
