   FPURAPPEND     VARCHAR(50) NOT NULL DEFAULT '' ,    -- 采购方附件
   FHASREAD     INT NOT NULL DEFAULT 0 ,    -- 已读状态
   FHASREADTIME     DATE NULL  ,    -- 已读时间
   FREFUREASON     VARCHAR(50) NOT NULL DEFAULT '' ,    -- 改善理由
