   FQTY     DECIMAL(24,6) NOT NULL DEFAULT 0 ,    -- 累计加工数量
   FUNITID     VARCHAR(50) NOT NULL DEFAULT '' ,    -- 常用单位
   FBASEUNITID     VARCHAR(50) NOT NULL DEFAULT '' ,    -- 基本单位
   FNOTE     NVARCHAR(max) NOT NULL DEFAULT '' ,    -- 备注
   FQUAQTY     DECIMAL(24,6) NOT NULL DEFAULT 0 ,    -- 累计合格数量
   FFAILQTY     DECIMAL(24,6) NOT NULL DEFAULT 0 ,    -- 累计不合格数量
   FSTARTTIME     DATETIME NULL  ,    -- 开工时间
   FINTERID	    VARCHAR(50)		NOT NULL DEFAULT '',	-- 表内码 
   FENTRYID		INT             NOT NULL DEFAULT 0 ,	-- 行号 
   FBODYID       VARCHAR(50)     NOT NULL DEFAULT '' ,   --父阶表体内码 
   FDETAILID     VARCHAR(50)     NOT NULL DEFAULT '' ,   --表体内码 
   FSTATUS		    INT NOT NULL DEFAULT 0 ,	 -- 状态 
   FDELETED          BIT NOT NULL DEFAULT  0 ,    --禁用状态 0 = 正常 1 = 禁用 
   FCOMPANYID	    VARCHAR(50)		NOT NULL DEFAULT '',	-- 组织代码 
