   C_USER				VARCHAR(20)		NOT NULL DEFAULT '',	-- 资料创建帐号
   M_YMD				DATETIME		NULL,		            -- 最后异动日期
   M_USER				VARCHAR(20)		NOT NULL DEFAULT '',	-- 最后异动帐号
   UID VARCHAR(50) NOT NULL CONSTRAINT [PK_T_PRD_MOPROCESS] PRIMARY KEY NONCLUSTERED
 ) 
END
